const { db, getCairoNow, getCairoDate } = require('./db');
const { logAudit } = require('./audit');

/**
 * Comprehensive safe cleanup: Removes duplicate or auto-generated tuition charges for October 2026,
 * ensuring all student balances and payment statuses remain exactly as recorded by the user.
 */
function cleanupAutoGeneratedCharges() {
  try {
    let deletedCount = 0;

    // 1. Delete any auto-generated charges matching October 2026 description where paid_amount = 0
    const explicitAuto = db.prepare(`
      SELECT id, student_id, description, net_amount
      FROM student_charges
      WHERE (
        description LIKE 'مصروفات شهرية (أكتوبر 2026)%'
        OR description LIKE '%(أكتوبر 2026)%'
      ) AND paid_amount = 0
    `).all();

    for (const ch of explicitAuto) {
      db.prepare('DELETE FROM student_charges WHERE id = ?').run(ch.id);
      deletedCount++;
    }

    // 2. Scan every student: if they have multiple tuition charges for October 2026, keep only the original/paid one
    const students = db.prepare('SELECT id, full_name, code FROM students').all();
    for (const st of students) {
      const tuitionCharges = db.prepare(`
        SELECT id, description, amount, net_amount, paid_amount, created_at
        FROM student_charges
        WHERE student_id = ?
          AND charge_type = 'tuition'
          AND (
            billing_month = '2026-10'
            OR due_date LIKE '2026-10%'
            OR charge_date LIKE '2026-10%'
            OR description LIKE '%2026-10%'
            OR description LIKE '%أكتوبر%'
          )
        ORDER BY id ASC
      `).all(st.id);

      if (tuitionCharges.length > 1) {
        // Separate paid and unpaid
        const paidCharges = tuitionCharges.filter(c => Number(c.paid_amount) > 0);
        const unpaidCharges = tuitionCharges.filter(c => Number(c.paid_amount) === 0);

        if (paidCharges.length > 0 && unpaidCharges.length > 0) {
          // Keep the paid one(s), remove the unpaid duplicate(s)
          for (const unp of unpaidCharges) {
            db.prepare('DELETE FROM student_charges WHERE id = ?').run(unp.id);
            deletedCount++;
          }
        } else if (unpaidCharges.length > 1) {
          // All are unpaid: keep the first (original enrollment charge), delete subsequent duplicates
          for (let i = 1; i < unpaidCharges.length; i++) {
            db.prepare('DELETE FROM student_charges WHERE id = ?').run(unpaidCharges[i].id);
            deletedCount++;
          }
        }
      }
    }

    if (deletedCount > 0) {
      console.log(`[Data Restored] Successfully cleaned ${deletedCount} duplicate/auto-generated charges. All balances restored to exact manual state.`);
    }
    return deletedCount;
  } catch (err) {
    console.error('Cleanup error:', err);
    return 0;
  }
}


/**
 * Run automated scheduled routines:
 * 1. Auto-generate monthly tuition charges for the current month
 * 2. Overdue tuition fees scan
 * 3. Upcoming payment deadlines (3 days ahead)
 * 4. Unpaid payroll obligations
 */
function runScheduledTasks() {
  const today = getCairoDate(); // 'YYYY-MM-DD'
  const [currentYear, currentMonth, currentDay] = today.split('-').map(Number);
  const currentMonthKey = `${currentYear}-${String(currentMonth).padStart(2, '0')}`;

  let overdueCount = 0;
  let upcomingCount = 0;
  let unpaidSalariesCount = 0;

  try {
    // Revert and clean up any accidental auto-generated charges to preserve user's exact balances
    cleanupAutoGeneratedCharges();

    // 1. Scan for Overdue Tuition:
    // Active students whose due day of the month <= currentDay, and have unpaid/partially paid charges
    const overdueStudents = db.prepare(`
      SELECT s.id, s.code, s.full_name, s.payment_due_day,
             COALESCE(SUM(c.net_amount - c.paid_amount), 0) as balance
      FROM students s
      JOIN student_charges c ON s.id = c.student_id
      WHERE s.status = 'active'
        AND c.status IN ('unpaid', 'partially_paid')
        AND date(c.due_date) < date(?)
      GROUP BY s.id
      HAVING balance > 0
    `).all(today);

    for (const st of overdueStudents) {
      overdueCount++;
      // Check if notification already logged today
      const existing = db.prepare(`
        SELECT id FROM notifications
        WHERE type = 'overdue_fee' AND link = ? AND date(created_at) = date(?)
      `).get(`/students/${st.id}`, today);

      if (!existing) {
        db.prepare(`
          INSERT INTO notifications (type, title, message, link, is_read, created_at)
          VALUES ('overdue_fee', ?, ?, ?, 0, ?)
        `).run(
          `رسوم دراسية متأخرة: ${st.full_name}`,
          `الطفل كود (${st.code}) لديه متأخرات مستحقة بقيمة ${st.balance} ج.م تجاوزت موعد الاستحقاق.`,
          `/students/${st.id}`,
          getCairoNow()
        );
      }
    }

    // 2. Upcoming Payment Deadlines (next 3 days):
    const threeDaysLater = new Date();
    threeDaysLater.setDate(threeDaysLater.getDate() + 3);
    const threeDaysStr = threeDaysLater.toLocaleDateString('sv-SE', { timeZone: 'Africa/Cairo' });

    const upcomingCharges = db.prepare(`
      SELECT s.id, s.code, s.full_name, c.net_amount - c.paid_amount as remaining, c.due_date
      FROM student_charges c
      JOIN students s ON c.student_id = s.id
      WHERE s.status = 'active'
        AND c.status IN ('unpaid', 'partially_paid')
        AND date(c.due_date) >= date(?)
        AND date(c.due_date) <= date(?)
    `).all(today, threeDaysStr);

    for (const ch of upcomingCharges) {
      upcomingCount++;
      const existing = db.prepare(`
        SELECT id FROM notifications
        WHERE type = 'upcoming_due' AND link = ? AND date(created_at) = date(?)
      `).get(`/students/${ch.id}`, today);

      if (!existing) {
        db.prepare(`
          INSERT INTO notifications (type, title, message, link, is_read, created_at)
          VALUES ('upcoming_due', ?, ?, ?, 0, ?)
        `).run(
          `موعد استحقاق قادم: ${ch.full_name}`,
          `يستحق قسط بقيمة ${ch.remaining} ج.م بتاريخ ${ch.due_date} للطفل كود (${ch.code}).`,
          `/students/${ch.id}`,
          getCairoNow()
        );
      }
    }

    // 3. Unpaid Salaries Check:
    const unpaidPayroll = db.prepare(`
      SELECT p.id, e.full_name, p.month, (p.net_salary - p.paid_amount) as remaining
      FROM payroll_records p
      JOIN employees e ON p.employee_id = e.id
      WHERE p.status IN ('unpaid', 'partially_paid')
    `).all();

    for (const pay of unpaidPayroll) {
      unpaidSalariesCount++;
      const existing = db.prepare(`
        SELECT id FROM notifications
        WHERE type = 'unpaid_salary' AND message LIKE ? AND date(created_at) = date(?)
      `).get(`%${pay.full_name}%`, today);

      if (!existing) {
        db.prepare(`
          INSERT INTO notifications (type, title, message, link, is_read, created_at)
          VALUES ('unpaid_salary', ?, ?, '/payroll', 0, ?)
        `).run(
          `مستحقات راتب غير مسددة: ${pay.full_name}`,
          `يوجد متبقي راتب بقيمة ${pay.remaining} ج.م لشهر ${pay.month}.`,
          getCairoNow()
        );
      }
    }

    logAudit({
      user: null,
      action: 'SCHEDULED_CHECK_COMPLETED',
      entityType: 'system_scheduler',
      entityId: today,
      details: { overdueCount, upcomingCount, unpaidSalariesCount }
    });

    return { success: true, overdueCount, upcomingCount, unpaidSalariesCount, checkedAt: getCairoNow() };
  } catch (err) {
    console.error('Scheduled tasks error:', err);
    logAudit({
      user: null,
      action: 'SCHEDULED_CHECK_FAILED',
      entityType: 'system_scheduler',
      entityId: today,
      reason: err.message
    });
    return { success: false, error: err.message };
  }
}

/**
 * Start background scheduler: runs once on server start, then every 6 hours
 */
function startScheduler() {
  // Run initial check after 5 seconds
  setTimeout(() => {
    runScheduledTasks();
  }, 5000);

  // Repeat every 6 hours (21600000 ms)
  setInterval(() => {
    runScheduledTasks();
  }, 6 * 60 * 60 * 1000);
}

module.exports = {
  runScheduledTasks,
  startScheduler,
  cleanupAutoGeneratedCharges
};
